WITH fuel_capacity_data AS (SELECT '{"SandcrawlerChassis_0":450.0,"SandcrawlerChassis_6":750.0,"SandcrawlerChassis_7":800.0,"BuggyChassis_0":220.0,"BuggyChassis_3":240.0,"BuggyChassis_4":260.0,"BuggyChassis_5":280.0,"BuggyChassis_6":300.0,"BuggyChassis_7":280.0,"BuggyChassis_8":340.0,"BuggyChassis_9":360.0,"OrnithopterMediumChassis_0":450.0,"OrnithopterMediumChassis_5":750.0,"OrnithopterMediumChassis_6":850.0,"OrnithopterMediumChassis_7":800.0,"TankChoamChassis":675.0,"TankChassis_0":350.0,"TankChassis_6":375.0,"TankChassis_7":400.0,"SandbikeChassis_0":90.0,"SandbikeChassis_1":100.0,"SandbikeChassis_2":110.0,"SandbikeChassis_3":120.0,"SandbikeChassis_4":130.0,"SandbikeChassis_5":140.0,"SandbikeChassis_6":150.0,"SandbikeChassis_7":140.0,"SandbikeChassis_8":170.0,"SandbikeChassis_9":180.0,"OrnithopterLightChassis_0":225.0,"OrnithopterLightChassis_4":300.0,"OrnithopterLightChassis_5":350.0,"OrnithopterLightChassis_6":400.0,"OrnithopterLightChassis_7":400.0,"OrnithopterTransportChassis_0":1350.0,"OrnithopterTransportChassis_6":2500.0,"OrnithopterTransportChassis_7":2400.0,"SeekerChassis":500.0,"TreadwheelChassis_0":90.0,"TreadwheelChassis_1":100.0,"TreadwheelChassis_2":110.0,"TreadwheelChassis_3":120.0,"TreadwheelChassis_4":130.0,"TreadwheelChassis_5":140.0,"TreadwheelChassis_6":150.0}'::jsonb AS capacities), chosen_markers AS (SELECT DISTINCT ON (map_name_id,marker_hash_id) * FROM dune.markers WHERE dimension_index IN (-1,0) ORDER BY map_name_id,marker_hash_id,CASE WHEN dimension_index=0 THEN 0 ELSE 1 END)
SELECT jsonb_build_object(
 'observedAt',clock_timestamp(),
 'readOnly',current_setting('transaction_read_only'),
 'seeds',(SELECT jsonb_object_agg(map,world_reset_seed) FROM dune.world_map_reset_seed),
 'servers',(SELECT jsonb_agg(jsonb_build_object('map',map,'ready',ready,'alive',alive,'players',connected_players)) FROM dune.farm_state),
 'vehicles',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id::text,'entityIds',(SELECT jsonb_agg(af.entity_id::text) FROM dune.actor_fgl_entities af WHERE af.actor_id=a.id),'class',a.class,'state',a.state,'map',a.map,'dimension',a.dimension_index,'location',to_jsonb((a.transform).location),'fuel',f.components->'FVehicleComponent'->1->'CurrentFuel','fuelCapacity',(SELECT CASE WHEN count(DISTINCT (fc.capacities->>m.template_id)::numeric)=1 THEN max((fc.capacities->>m.template_id)::numeric) END FROM dune.vehicle_modules m CROSS JOIN fuel_capacity_data fc WHERE m.vehicle_id=a.id AND fc.capacities ? m.template_id))),'[]') FROM dune.actors a JOIN dune.vehicles v ON v.id=a.id LEFT JOIN LATERAL (SELECT fe.components FROM dune.actor_fgl_entities af JOIN dune.fgl_entities fe ON fe.entity_id=af.entity_id WHERE af.actor_id=a.id AND fe.components ? 'FVehicleComponent' LIMIT 1) f ON true WHERE a.map IS NOT NULL AND a.state IS DISTINCT FROM 'VehicleBackup' AND a.state IS DISTINCT FROM 'VehicleRecovery' AND a.state IS DISTINCT FROM 'Travel'),
 'bases',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id::text,'map',a.map,'dimension',a.dimension_index,'location',to_jsonb((a.transform).location))),'[]') FROM dune.actors a JOIN dune.totems t ON t.id=a.id WHERE a.map IS NOT NULL AND a.state IS DISTINCT FROM 'BaseBackup'),
 'spice',(SELECT coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('field_id',r.field_id::text)),'[]') FROM dune.resourcefield_state r),
 'shifting',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM dune.shiftingsands_data s),
 'locations',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.marker_hash_id::text,'map',n.map_name,'dimension',m.dimension_index,'type',m.marker_type,'location',to_jsonb(m.position),'radius',m.area_radius,'areaId',m.area_id,'displayName',m.payload->>'DisplayName','tags',m.payload->>'StaticLocationTags','intelCount',CASE WHEN jsonb_typeof(m.payload->'IntelPickups')='array' THEN jsonb_array_length(m.payload->'IntelPickups') ELSE 0 END,'survey',EXISTS(SELECT 1 FROM dune.map_areas a WHERE a.survey_point_marker_id=m.marker_hash_id AND a.map_name=n.map_name))),'[]') FROM chosen_markers m JOIN dune.map_names n ON n.map_name_id=m.map_name_id WHERE n.map_name IN ('DeepDesert','HaggaBasin')),
 'events',(SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]') FROM (SELECT event_type,map,universe_time,x,y,z FROM dune.game_events ORDER BY universe_time DESC LIMIT 100) e)
)::text AS snapshot;
